<?php
declare(strict_types=1);
// Alle Angebote: offen (Entwurf/versendet) mit Nachfass-Hinweisen, angenommen, abgelehnt; Quote der letzten 12 Monate.
require __DIR__.'/bootstrap.php';if(empty($_SESSION['admin_id']))redirect('index.php');
require_once dirname(__DIR__).'/private/ui.php';require_once dirname(__DIR__).'/private/offers.php';
if(!gszOffersReady($pdo)){gszPageStart('Angebote');echo '<div class="empty"><strong>Update nötig.</strong>Angebote gibt es ab Stand 460 – bitte unter Einstellungen → Update aktualisieren.</div>';gszPageEnd();exit;}
$filter=(string)($_GET['f']??'');$rows=$pdo->query("SELECT * FROM offers ORDER BY FIELD(status,'versendet','entwurf','angenommen','abgelehnt'),COALESCE(followup_on,'9999-12-31'),id DESC LIMIT 1000")->fetchAll(PDO::FETCH_ASSOC);
$count=array_count_values(array_column($rows,'status'));$shown=$filter&&isset(GSZ_OFFER_STATUS[$filter])?array_filter($rows,fn($r)=>$r['status']===$filter):$rows;
$yearAgo=(new DateTimeImmutable('-12 months'))->format('Y-m-d');$won=0;$lost=0;$wonMonthly=0;foreach($rows as $r)if($r['decided_on']&&$r['decided_on']>=$yearAgo){if($r['status']==='angenommen'){$won++;$wonMonthly+=gszOfferTotals($r)['month']??0;}elseif($r['status']==='abgelehnt')$lost++;}
$att=gszOfferAttention($pdo);$today=date('Y-m-d');
gszPageStart('Angebote','Aus Anfragen – mit Erinnerung ans Nachfassen.');
foreach(['app_error'=>'error','app_notice'=>'notice'] as $k=>$cls)if(isset($_SESSION[$k])){echo '<p class="'.$cls.' flash" role="'.($cls==='error'?'alert':'status').'">'.e($_SESSION[$k]).'</p>';unset($_SESSION[$k]);}?>
<div class="estate-actions"><form method="post" action="angebot.php"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="create"><button class="primary">+ Neues Angebot</button></form><a class="btn" href="leads.php">Aus einer Anfrage …</a></div>
<nav class="day-kpis" aria-label="Angebote"><a class="dk<?=($count['versendet']??0)?' is-warn':''?>" href="?f=versendet"><strong><?=$count['versendet']??0?></strong><span>offen beim Kunden</span></a><a class="dk" href="?f=entwurf"><strong><?=$count['entwurf']??0?></strong><span>Entwürfe</span></a><a class="dk" href="?f=angenommen"><strong><?=$won?></strong><span>angenommen (12 Mon.)</span><?php if($wonMonthly):?><small>+ <?=e(moneyDisplay($wonMonthly))?> / Monat</small><?php endif?></a><div class="dk"><strong><?=$won+$lost?(int)round(100*$won/($won+$lost)).' %':'–'?></strong><span>Erfolgsquote</span></div></nav>
<?php if($att):?><h2 class="section-title">Heute nachfassen</h2><div class="task-feed"><?php foreach($att as [$u,$t]):?><a class="tf tf-amber" href="<?=e($u)?>"><span class="tf-dot" aria-hidden="true"></span><span><strong><?=e($t)?></strong></span></a><?php endforeach?></div><?php endif?>
<nav class="seg-tabs" aria-label="Filter"><a href="angebote.php"<?=!$filter?' aria-current="page"':''?>>Alle <span class="count"><?=count($rows)?></span></a><?php foreach(GSZ_OFFER_STATUS as $k=>[$l]):if(empty($count[$k]))continue;?><a href="?f=<?=$k?>"<?=$filter===$k?' aria-current="page"':''?>><?=e($l)?> <span class="count"><?=$count[$k]?></span></a><?php endforeach?></nav>
<?php if(!$shown):?><div class="empty"><strong>Noch keine Angebote.</strong>Bei einer Anfrage auf „Angebot erstellen“ tippen – Name, Kontakt und Leistung sind dann schon drin.</div><?php else:?><div class="list"><?php foreach($shown as $r):[$l,$cls]=GSZ_OFFER_STATUS[$r['status']];$due=$r['status']==='versendet'&&$r['followup_on']&&$r['followup_on']<=$today;?>
<a href="angebot.php?id=<?=(int)$r['id']?>"><span class="name"><?=e($r['client_name']?:'(ohne Kunde)')?><span class="sub"><?=e(gszOfferNo($r))?><?=$r['object_name']!==''?' · '.e($r['object_name']):''?> · <?=e(gszOfferTotalText($r))?><?=$r['sent_on']?' · versendet '.e((new DateTimeImmutable($r['sent_on']))->format('d.m.')):''?><?=$due?' · <strong>nachfassen</strong>':''?></span></span><span class="pill <?=e($due?'part':$cls)?>"><?=e($l)?></span></a><?php endforeach?></div><?php endif?>
<?php gszPageEnd();
